#!/usr/bin/env python3
"""
Update HWPX renewal playbook document with new data from JSON and CSV files.
"""

import json
import csv
import zipfile
import xml.etree.ElementTree as ET
import os
import shutil
import re

def read_inputs():
    """Read the JSON update data and CSV followups."""
    with open('/root/renewal_update.json', 'r', encoding='utf-8') as f:
        update_data = json.load(f)

    followups = []
    with open('/root/followups.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            followups.append({
                'sequence': int(row['sequence']),
                'item': row['item']
            })
    followups.sort(key=lambda x: x['sequence'])

    return update_data, followups


def register_namespaces(xml_file):
    """Extract and register all namespace prefixes from an XML file."""
    with open(xml_file, 'r', encoding='utf-8') as f:
        content = f.read()

    # Find all xmlns declarations
    ns_pattern = r'xmlns:([^=]+)="([^"]+)"'
    matches = re.findall(ns_pattern, content)

    for prefix, uri in matches:
        ET.register_namespace(prefix, uri)

    # Also check for default namespace (xmlns without prefix)
    default_ns_pattern = r'xmlns="([^"]+)"'
    default_matches = re.findall(default_ns_pattern, content)
    for uri in default_matches:
        ET.register_namespace('', uri)


def get_namespace_prefixes(xml_file):
    """Get a dictionary of namespace prefixes from the XML file."""
    with open(xml_file, 'r', encoding='utf-8') as f:
        content = f.read()

    ns_map = {}
    ns_pattern = r'xmlns:([^=]+)="([^"]+)"'
    matches = re.findall(ns_pattern, content)
    for prefix, uri in matches:
        ns_map[prefix] = uri

    # Default namespace
    default_ns_pattern = r'xmlns="([^"]+)"'
    default_matches = re.findall(default_ns_pattern, content)
    for uri in default_matches:
        ns_map[''] = uri

    return ns_map


def find_text_elements(element, ns_map):
    """Find all text-bearing elements (<hp:t> or similar)."""
    text_elements = []
    hp_ns = ns_map.get('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

    for elem in element.iter():
        if elem.tag == f'{{{hp_ns}}}t' or elem.tag.endswith('}t'):
            text_elements.append(elem)

    return text_elements


def find_parent_paragraph(element, ns_map):
    """Find the parent paragraph (<hp:p>) of an element."""
    hp_ns = ns_map.get('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')
    parent = element

    while parent is not None:
        if parent.tag == f'{{{hp_ns}}}p' or parent.tag.endswith('}p'):
            return parent
        parent = parent.find('..') if hasattr(parent, 'find') else None

    return None


def remove_layout_cache(paragraph, ns_map):
    """Remove layout cache elements from a paragraph."""
    hp_ns = ns_map.get('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

    # Find and remove linesegarray, lineseg elements
    to_remove = []
    for child in list(paragraph):
        tag_local = child.tag.split('}')[-1] if '}' in child.tag else child.tag
        if 'lineseg' in tag_local.lower() or 'linesegarray' in tag_local.lower():
            to_remove.append(child)

    for child in to_remove:
        paragraph.remove(child)


def process_section(xml_file, update_data, followups, modified_paragraphs):
    """Process a section XML file and apply updates."""
    # Register namespaces first
    register_namespaces(xml_file)
    ns_map = get_namespace_prefixes(xml_file)
    hp_ns = ns_map.get('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

    tree = ET.parse(xml_file)
    root = tree.getroot()

    # Build old value mappings
    old_customer = "Northwind Retail"
    old_owner = "이전담당자"
    old_window = "2025-04-01 ~ 2025-04-15"
    new_window = f"{update_data['window_start']} ~ {update_data['window_end']}"
    old_band = "Standard-18M"
    old_escalation = "ops-old@northwind.example"
    old_note_prefix = "가격 메모: "
    old_note_content = "기존 메모를 새 메모로 바꾸세요."

    # Follow-up mappings (old values)
    old_followups = [
        "1. old follow-up alpha",
        "2. old follow-up beta",
        "3. old follow-up gamma"
    ]

    # Build parent mapping for all elements
    parent_map = {}
    for parent in root.iter():
        for child in parent:
            parent_map[child] = parent

    # Track which paragraphs were modified
    modified_p_ids = set()

    # Find all text elements and their parent paragraphs
    for para in root.iter(f'{{{hp_ns}}}p'):
        para_id = para.get('id')
        text_content = ""
        text_elems_in_para = []

        # Collect all text elements in this paragraph
        for run in para.iter(f'{{{hp_ns}}}run'):
            for t_elem in run.iter(f'{{{hp_ns}}}t'):
                if t_elem.text:
                    text_content += t_elem.text
                text_elems_in_para.append(t_elem)

        if not text_elems_in_para:
            continue

        modified = False

        # Check if this paragraph contains text we need to update
        full_text = "".join(te.text or "" for te in text_elems_in_para)

        # Skip the appendix preservation sentence
        if "이 부록 문단은 그대로 유지해야 합니다." in full_text:
            continue

        # Replace customer name (Northwind Retail)
        if old_customer in full_text:
            # Clear and rebuild text elements
            new_text = full_text.replace(old_customer, update_data['customer'])
            if len(text_elems_in_para) == 1:
                text_elems_in_para[0].text = new_text
            else:
                # Multiple runs - combine into first, clear others
                text_elems_in_para[0].text = new_text
                for te in text_elems_in_para[1:]:
                    te.text = ""
            modified = True

        # Replace owner
        elif old_owner in full_text:
            new_text = full_text.replace(old_owner, update_data['owner_name'])
            if len(text_elems_in_para) == 1:
                text_elems_in_para[0].text = new_text
            else:
                text_elems_in_para[0].text = new_text
                for te in text_elems_in_para[1:]:
                    te.text = ""
            modified = True

        # Replace window dates
        elif old_window in full_text:
            new_text = full_text.replace(old_window, new_window)
            if len(text_elems_in_para) == 1:
                text_elems_in_para[0].text = new_text
            else:
                text_elems_in_para[0].text = new_text
                for te in text_elems_in_para[1:]:
                    te.text = ""
            modified = True

        # Replace pricing band
        elif old_band in full_text:
            new_text = full_text.replace(old_band, update_data['band'])
            if len(text_elems_in_para) == 1:
                text_elems_in_para[0].text = new_text
            else:
                text_elems_in_para[0].text = new_text
                for te in text_elems_in_para[1:]:
                    te.text = ""
            modified = True

        # Replace escalation email
        elif old_escalation in full_text:
            new_text = full_text.replace(old_escalation, update_data['escalation_email'])
            if len(text_elems_in_para) == 1:
                text_elems_in_para[0].text = new_text
            else:
                text_elems_in_para[0].text = new_text
                for te in text_elems_in_para[1:]:
                    te.text = ""
            modified = True

        # Replace pricing note
        elif old_note_content in full_text:
            new_text = full_text.replace(old_note_content, update_data['note'])
            if len(text_elems_in_para) == 1:
                text_elems_in_para[0].text = new_text
            else:
                text_elems_in_para[0].text = new_text
                for te in text_elems_in_para[1:]:
                    te.text = ""
            modified = True

        # Replace follow-ups
        for i, old_fu in enumerate(old_followups):
            if old_fu in full_text:
                new_fu = f"{i+1}. {followups[i]['item']}"
                new_text = full_text.replace(old_fu, new_fu)
                if len(text_elems_in_para) == 1:
                    text_elems_in_para[0].text = new_text
                else:
                    text_elems_in_para[0].text = new_text
                    for te in text_elems_in_para[1:]:
                        te.text = ""
                modified = True
                break

        if modified:
            modified_p_ids.add(para_id)
            # Remove layout cache elements from this paragraph
            remove_layout_cache(para, ns_map)

    # Also handle table cells (hp:tc elements contain hp:subList with hp:p)
    for tc in root.iter(f'{{{hp_ns}}}tc'):
        for sublist in tc.iter(f'{{{hp_ns}}}subList'):
            for para in sublist.iter(f'{{{hp_ns}}}p'):
                para_id = para.get('id')
                text_elems_in_para = []

                for run in para.iter(f'{{{hp_ns}}}run'):
                    for t_elem in run.iter(f'{{{hp_ns}}}t'):
                        if t_elem.text:
                            text_elems_in_para.append(t_elem)

                if not text_elems_in_para:
                    continue

                full_text = "".join(te.text or "" for te in text_elems_in_para)
                modified = False

                # Replace pricing band in table
                if old_band in full_text:
                    new_text = full_text.replace(old_band, update_data['band'])
                    if len(text_elems_in_para) == 1:
                        text_elems_in_para[0].text = new_text
                    else:
                        text_elems_in_para[0].text = new_text
                        for te in text_elems_in_para[1:]:
                            te.text = ""
                    modified = True

                # Replace escalation in table
                elif old_escalation in full_text:
                    new_text = full_text.replace(old_escalation, update_data['escalation_email'])
                    if len(text_elems_in_para) == 1:
                        text_elems_in_para[0].text = new_text
                    else:
                        text_elems_in_para[0].text = new_text
                        for te in text_elems_in_para[1:]:
                            te.text = ""
                    modified = True

                if modified:
                    modified_p_ids.add(para_id)
                    remove_layout_cache(para, ns_map)

    # Write the modified XML back with proper XML declaration
    tree.write(xml_file, encoding='UTF-8', xml_declaration=True)

    return modified_p_ids


def create_updated_hwpx(extracted_dir, output_path):
    """Create the updated HWPX file from the extracted directory."""
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for root, dirs, files in os.walk(extracted_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, extracted_dir)
                zipf.write(file_path, arcname)


def main():
    # Read input data
    update_data, followups = read_inputs()
    print(f"Update data: {update_data}")
    print(f"Followups: {followups}")

    # Setup directories
    extracted_dir = '/tmp/hwpx_work/extracted'
    os.makedirs(extracted_dir, exist_ok=True)

    # Extract the HWPX file
    with zipfile.ZipFile('/root/renewal_playbook.hwpx', 'r') as z:
        z.extractall(extracted_dir)

    # Track modified paragraphs
    modified_paragraphs = set()

    # Process section files
    section_files = [
        os.path.join(extracted_dir, 'Contents', 'section0.xml'),
        os.path.join(extracted_dir, 'Contents', 'section1.xml')
    ]

    for section_file in section_files:
        if os.path.exists(section_file):
            print(f"Processing {section_file}...")
            modified = process_section(section_file, update_data, followups, modified_paragraphs)
            print(f"  Modified paragraphs: {modified}")

    # Create the updated HWPX file
    output_path = '/root/renewal_playbook_updated.hwpx'
    create_updated_hwpx(extracted_dir, output_path)
    print(f"Created updated HWPX: {output_path}")


if __name__ == '__main__':
    main()

